-- F1.2 — référentiel codes postaux → commune la plus peuplée + coordonnées.
-- Source : geo.api.gouv.fr (communes, centres, population), licence ouverte.
-- Sert la « ville approximative » (F1.2) et le tri par distance (F2.1).
CREATE TABLE communes (
    code_postal TEXT PRIMARY KEY CHECK (code_postal ~ '^[0-9]{5}$'),
    nom         TEXT NOT NULL,
    lat         DOUBLE PRECISION NOT NULL,
    lng         DOUBLE PRECISION NOT NULL
);

